(function(root){
// Fictional life paths: context gates opportunities; numbers are game points.
function ensure(s){const f=s.flow;if(!f.decisions){const education=s.history.find(h=>h.choice==='Продолжить образование'||h.choice==='Освоить профессию на практике');f.decisions={version:1,focus:'health',seen:[],education:education?.choice==='Продолжить образование'?'university':education?'vocational':s.age>=17?'none':'school',job:s.flow.career.currentJob?'Работа':null,retired:false,home:'Родной город',annual:{},lastMonth:f.months};if(s.social?.partner)f.decisions.partner=s.social.partner.name;if(f.relationshipSeen)f.decisions.seen.push('date');if(education&&s.age===17)f.decisions.seen.push('education');for(const event of events)if(event.age<s.age)f.decisions.seen.push(event.id);}return f.decisions;}
const option=(title,note,effect={},change={},hint='')=>({title,note,effect,change,hint});
const events=[
{id:'school',age:6,title:'После школы',text:'Можно записаться на одно занятие. Что попробуете?',scene:'school',options:()=>[option('Кружок','Вы записались в школьный кружок.',{skill:3},{club:'learn'}),option('Спорт','После уроков вы ходите на тренировки.',{health:3},{club:'sport'}),option('Рисование','Вы начали рисовать в студии.',{joy:3},{club:'art'})]},
{id:'teen',age:12,title:'Летние планы',text:'На каникулах есть время для одного большого занятия.',scene:'park',options:()=>[option('Учебный курс','Вы прошли летний курс.',{skill:4,money:-2}),option('Поездка с семьёй','Вы провели каникулы с близкими.',{bond:4,joy:3}),option('Свой проект','Вы закончили первый самостоятельный проект.',{skill:2,joy:3})]},
{id:'education',age:17,title:'После школы',text:'Школа заканчивается. Какой путь выберете?',scene:'school',options:(d,s)=>[option('Университет',s.stats.skill>=35?'Вы поступили в университет и получили учебную стипендию.':'Вы поступили в университет.',{money:s.stats.skill>=35?-2:-6},{education:'university'},s.stats.skill>=35?'4 года учёбы · со стипендией':'4 года учёбы → работа по специальности'),option('Колледж','Вы поступили в колледж.',{money:-3},{education:'vocational'},'2 года обучения профессии'),option('Начать работать','Вы нашли первую работу без специальной подготовки.',{money:3},{education:'none',job:'Первая работа'})]},
{id:'college-end',age:19,when:d=>d.education==='vocational',title:'Диплом колледжа',text:'Обучение окончено. Мастерская предлагает работу по профессии.',scene:'work',options:()=>[option('Принять работу','Вы начали работать по полученной профессии.',{money:4},{education:'qualified',job:'Мастерская'}),option('Искать другое','Вы получили диплом и продолжаете искать подходящую работу.',{skill:2},{education:'qualified'})]},
{id:'university-end',age:21,when:d=>d.education==='university',title:'После университета',text:'У вас диплом. Можно начать работу по специальности или искать свой путь.',scene:'read',options:()=>[option('По специальности','Вы получили первую работу по специальности.',{money:4,skill:3},{education:'graduate',job:'Работа по специальности'}),option('Другой путь','Вы получили диплом и решили попробовать другую сферу.',{joy:3},{education:'graduate'})]},
{id:'job',age:23,title:'Предложение работы',scene:'work',text:'Знакомая организация набирает сотрудников. Что вам подходит?',options:(d,s)=>[...(d.education==='graduate'&&s.stats.skill>=35?[option('Специалист','Вы приняли предложение на должность специалиста.',{money:6},{job:'Специалист'})]:[]),option('Работа с обучением','Вы начали новую работу с обучением на месте.',{money:3,skill:2},{job:'Работа с обучением'}),option('Оставить как есть','Вы решили пока сохранить привычный ритм.',{joy:1})]},
{id:'date',age:25,when:d=>!d.partner,title:'Приглашение на свидание',text:'Вы сблизились с Алексом. Вас зовут провести вечер вдвоём.',scene:'park',options:()=>[option('Пойти','Первое свидание стало началом ваших отношений.',{joy:4,bond:3},{partner:'Алекс'}),option('Отказаться','Вы решили сохранить знакомство без романтических отношений.',{})]},
{id:'together',age:30,when:d=>Boolean(d.partner),title:'Жить вместе',text:'Алекс предлагает найти общий дом.',scene:'family',options:()=>[option('Съехаться','Вы начали жить вместе.',{money:-3,joy:4},{livingTogether:true}),option('Пока отдельно','Вы продолжаете встречаться и жить отдельно.',{bond:1})]},
{id:'move',age:34,title:'Другой город',text:'Есть возможность переехать. Привычные места и близкие останутся здесь.',scene:'park',options:()=>[option('Переехать','Вы переехали в другой город и начали обустраиваться.',{money:-6,joy:2},{home:'Новый город'}),option('Остаться','Вы решили остаться в родном городе.',{bond:3})]},
{id:'promotion',age:40,when:d=>Boolean(d.job),title:'Больше ответственности',text:'На работе предлагают повышение. Доход вырастет, свободного времени станет меньше.',scene:'work',options:()=>[option('Принять','Вы приняли повышение.',{money:7,joy:-2},{promoted:true}),option('Сохранить ритм','Вы сохранили прежнюю должность и время для себя.',{joy:3})]},
{id:'new-work',age:40,when:d=>!d.job,title:'Работа рядом с домом',text:'В местном центре появилась вакансия с обучением.',scene:'work',options:()=>[option('Попробовать','Вы начали работать в местном центре.',{money:3},{job:'Местный центр'}),option('Отказаться','Вы решили пока не менять свой ритм.',{joy:1})]},
{id:'health',age:48,title:'Новый ритм',text:'Последнее время вы быстрее устаёте. Как освободить время для восстановления?',scene:'home',options:()=>[option('Снизить нагрузку','Вы пересмотрели расписание и стали больше отдыхать.',{health:4,money:-2}),option('Добавить прогулки','В вашем расписании появились регулярные прогулки.',{health:2,joy:2})]},
{id:'connections',age:56,title:'Время для близких',text:'Вы давно хотели устроить встречу без повода.',scene:'family',options:()=>[option('Позвать всех','Вы собрали близких за одним столом.',{bond:4,joy:3,money:-2}),option('Встретиться вдвоём','У вас нашлось время для долгого разговора с близким человеком.',{bond:3,joy:2})]},
{id:'retirement',age:65,when:d=>Boolean(d.job),title:'Новый этап',text:'Можно завершить работу или пока сохранить часть занятий.',scene:'home',options:()=>[option('Завершить работу','Вы завершили работу. Появилось больше времени для себя.',{joy:3},{retired:true,job:null}),option('Работать меньше','Вы перешли на частичную занятость.',{money:2,joy:1},{partTime:true})]},
{id:'later',age:70,title:'Давно хотелось',text:'Теперь можно уделить больше времени тому, что вы откладывали.',scene:'draw',options:()=>[option('Вернуться к хобби','Вы вернулись к любимому занятию.',{joy:4}),option('Быть с близкими','Вы стали чаще встречаться с близкими.',{bond:4,joy:2})]},
{id:'memory',age:76,title:'Что сохранить',text:'Вы перебираете вещи и записи, накопленные за жизнь.',scene:'family',options:()=>[option('Собрать альбом','Вы собрали памятные моменты в альбом.',{joy:2}),option('Рассказать историю','Вы поделились своей историей с близкими.',{bond:2})]}
];
function pending(s){const d=ensure(s);const e=events.find(e=>e.age*12<=s.flow.months&&!d.seen.includes(e.id)&&(!e.when||e.when(d)));return e?{...e,kind:'life',options:e.options(d,s)}:null;}
function resolve(s,index){const d=ensure(s),e=pending(s),o=e?.options[index];if(!o)return null;const before={...s.stats};d.seen.push(e.id);Object.assign(d,o.change);for(const [key,value]of Object.entries(o.effect))s.stats[key]=Math.max(0,Math.min(100,s.stats[key]+value));if(o.change.partner)s.social.partner={name:d.partner,closeness:65,values:'independent',changed:false};if(e.id==='memory')s.ended=true;return {scene:o.change.job?'work':o.change.education==='university'||o.change.education==='vocational'?'read':e.scene,age:s.age,title:e.title,choice:o.title,text:o.note,delta:Object.fromEntries(Object.keys(o.effect).map(k=>[k,s.stats[k]-before[k]]))};}
function focuses(s){const d=ensure(s);if(s.age<6||s.ended)return [];return [{id:'health',title:'Здоровье',effect:{health:2,joy:1}},{id:'learn',title:'Учёба',effect:{skill:3}},{id:'people',title:'Близкие',effect:{bond:3,joy:2}},{id:'create',title:'Увлечения',effect:{skill:1,joy:3}},...(d.job&&!d.retired?[{id:'work',title:'Работа',effect:{money:4,health:-1,joy:-1}}]:[])];}
function setFocus(s,id){const d=ensure(s);if(!focuses(s).some(f=>f.id===id))return false;d.focus=id;return true;}
function tick(s){const d=ensure(s);if(d.lastMonth===s.flow.months)return;d.lastMonth=s.flow.months;const choices=focuses(s);if(!choices.some(f=>f.id===d.focus))d.focus='health';const focus=choices.find(f=>f.id===d.focus);if(focus)for(const [k,v]of Object.entries(focus.effect))d.annual[k]=(d.annual[k]||0)+v/12;if(s.flow.months%12===0){for(const [k,v]of Object.entries(d.annual))s.stats[k]=Math.max(0,Math.min(100,s.stats[k]+Math.round(v)));if(d.job&&!d.retired)s.stats.money=Math.min(100,s.stats.money+(d.partTime?1:d.promoted?3:2));if(d.education==='university'||d.education==='vocational')s.stats.money=Math.max(0,s.stats.money-1);if(focus)s.flow.activity={health:'park',learn:s.age<17?'school':'read',people:'family',create:'draw',work:'work'}[d.focus];d.annual={};}}
function occupation(s){const d=ensure(s);return s.age<6?'Дошкольница':s.age<17?'Школьница':d.education==='university'||d.education==='vocational'?'Студентка':d.job|| (d.retired?'На пенсии':'Свободный ритм');}
root.LifeDecisions={ensure,pending,resolve,focuses,setFocus,tick,occupation};if(typeof module!=='undefined')module.exports=root.LifeDecisions;
})(typeof window!=='undefined'?window:globalThis);
